args.code:
const tabId = 787784560;
// Check if we can interact with CryptPad inside the iframe or page
const result = await browserjs(tabId, () => {
  const iframe = document.querySelector('iframe');
  if (!iframe) return { error: "no outer iframe" };
  try {
    const doc = iframe.contentDocument || iframe.contentWindow.document;
    const titleEl = doc.querySelector('.cp-toolbar-title');
    const editorEl = doc.querySelector('.cke_editable') || doc.querySelector('[contenteditable="true"]');
    return {
      titleText: titleEl ? titleEl.textContent : null,
      hasEditor: !!editorEl,
      url: window.location.href
    };
  } catch (e) {
    return { error: e.toString() };
  }
});
console.log("CryptPad inspection:", result);

